// RunDue attempts every delivery that is due and returns how many it attempted. Each delivery is attempted once: an answer
// with a 2xx status marks it succeeded, anything else failed.
func (s *Service) RunDue(ctx context.Context) (int, error) {
	n := 0
	for _, d := range s.store.DueDeliveries(s.clock.Now()) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		s.deliver(ctx, d)
		n++
	}
	return n, nil
}

args.new_string:
// RunDue attempts every delivery that is due and returns how many it attempted. An answer with a 2xx status marks a delivery
// succeeded. Any other failure schedules a retry (see retryWaits) until the delivery has had maxAttempts attempts; a 410 Gone
// answer fails it at once and disables its endpoint.
func (s *Service) RunDue(ctx context.Context) (int, error) {
	n := 0
	for _, d := range s.store.DueDeliveries(s.clock.Now()) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		// An earlier attempt in this run may have disabled the endpoint, which unschedules its other deliveries.
		if cur, ok := s.store.Delivery(d.ID); !ok || cur.Status != store.DeliveryPending || cur.NextAttemptAt == nil {
			continue
		}
		s.deliver(ctx, d)
		n++
	}
	return n, nil
}

