	e.HTTP.Respond = func(apitest.Request) (int, error) { return http.StatusBadGateway, nil }
	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}

	// The waits after the first to the sixth failed attempt, each counted from the failed attempt before it.
	waits := []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
	for attempt := 1; attempt <= 7; attempt++ {
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("attempt %d: RunDue = %d, %v", attempt, n, err)
		}
		at := e.Clock.Now()
		d := e.Store.Deliveries(e.Acme.ID, ep.ID)[0]
		if d.Attempts != attempt || d.ResponseStatus != http.StatusBadGateway || d.Error == "" || d.LastAttemptAt == nil || !d.LastAttemptAt.Equal(at) {
			t.Fatalf("after attempt %d: %+v", attempt, d)
		}
		if attempt == 7 {
			if d.Status != store.DeliveryFailed || d.NextAttemptAt != nil {
				t.Fatalf("after the last attempt: %+v", d)
			}
			raw, _ := json.Marshal(d)
			if !strings.Contains(string(raw), `"next_attempt_at":null`) {
				t.Fatalf("next_attempt_at is not null: %s", raw)
			}
			break
		}
		if d.Status != store.DeliveryPending || d.NextAttemptAt == nil || !d.NextAttemptAt.Equal(at.Add(waits[attempt-1])) {
			t.Fatalf("after attempt %d: next attempt at %v, want %v", attempt, d.NextAttemptAt, at.Add(waits[attempt-1]))
		}
		e.Clock.Advance(waits[attempt-1] - time.Second)
		if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
			t.Fatalf("attempt %d was due a second early", attempt+1)
		}
		e.Clock.Advance(time.Second)
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("RunDue after the last attempt = %d", n)
	}
	if got := len(e.HTTP.Requests()); got != 7 {
		t.Fatalf("requests = %d, want 7", got)
	}
	msgs := e.Mail.Messages()
	if len(msgs) != 1 || msgs[0].To != "owner@acme.example" || msgs[0].Subject != "Webhook endpoint failing: "+ep.URL {
		t.Fatalf("mail = %+v", msgs)
	}
}

