// runRetries runs the due deliveries and moves the clock to the next planned attempt, until none of the endpoint's
// deliveries is pending.
func runRetries(t *testing.T, e *apitest.Env, org apitest.Org, endpointID string) {
	t.Helper()
	for range 20 {
		if _, err := e.Webhooks.RunDue(context.Background()); err != nil {
			t.Fatal(err)
		}
		var next *time.Time
		for _, d := range e.Store.Deliveries(org.ID, endpointID) {
			if d.Status == store.DeliveryPending && d.NextAttemptAt != nil && (next == nil || d.NextAttemptAt.Before(*next)) {
				next = d.NextAttemptAt
			}
		}
		if next == nil {
			return
		}
		e.Clock.Set(*next)
	}
	t.Fatal("deliveries still pending after 20 rounds")
}

