1	// Package webhooks sends an organization's events to its webhook endpoints.
2	package webhooks
3	
4	import (
5		"bytes"
6		"context"
7		"crypto/hmac"
8		"crypto/sha256"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"io"
14		"net"
15		"net/http"
16		"net/url"
17		"slices"
18		"sync"
19		"time"
20	
21		"example.com/tally/internal/clock"
22		"example.com/tally/internal/mail"
23		"example.com/tally/internal/store"
24	)
25	
26	// retryWaits are the waits after the first to the sixth failed attempt; each counts from the failed attempt before it.
27	var retryWaits = []time.Duration{time.Minute, 5 * time.Minute, 30 * time.Minute, 2 * time.Hour, 8 * time.Hour, 24 * time.Hour}
28	
29	// maxAttempts is how many attempts a delivery gets before it fails for good.
30	var maxAttempts = len(retryWaits) + 1
31	
32	// failureMailInterval is the least time between two emails about the same endpoint.
33	const failureMailInterval = 24 * time.Hour
34	
35	// Doer sends HTTP requests (an *http.Client).
36	type Doer interface {
37		Do(*http.Request) (*http.Response, error)
38	}
39	
40	// Resolver looks up host names (a *net.Resolver).
41	type Resolver interface {
42		LookupIPAddr(ctx context.Context, host string) ([]net.IPAddr, error)
43	}
44	
45	// Options configure a Service.
46	type Options struct {
47		Store *store.Store
48		Clock clock.Clock
49		// Doer sends the deliveries; nil means an HTTP client with a 10 second timeout that does not follow redirects.
50		Doer Doer
51		// Resolver checks endpoint hosts; nil means net.DefaultResolver.
52		Resolver Resolver
53		// Mail sends the emails about endpoints whose deliveries fail for good; nil means an Outbox (nothing is sent).
54		Mail mail.Sender
55	}
56	
57	// Service manages endpoints' URLs and sends deliveries.
58	type Service struct {
59		store    *store.Store
60		clock    clock.Clock
61		doer     Doer
62		resolver Resolver
63		mail     mail.Sender
64	
65		mu     sync.Mutex
66		mailed map[string]time.Time // when each endpoint was last emailed about a failing delivery
67	}
68	
69	// New returns a Service.
70	func New(opt Options) *Service {
71		s := &Service{store: opt.Store, clock: opt.Clock, doer: opt.Doer, resolver: opt.Resolver, mail: opt.Mail, mailed: map[string]time.Time{}}
72		if s.clock == nil {
73			s.clock = clock.Real{}
74		}
75		if s.doer == nil {
76			s.doer = &http.Client{Timeout: 10 * time.Second, CheckRedirect: func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }}
77		}
78		if s.resolver == nil {
79			s.resolver = net.DefaultResolver
80		}
81		if s.mail == nil {
82			s.mail = &mail.Outbox{}
83		}
84		return s
85	}
86	
87	// EventTypes are the events Tally sends. An endpoint subscribes to some of them, or to "*" for all.
88	var EventTypes = []string{
89		"customer.created", "customer.updated", "customer.deleted",
90		"subscription.created", "subscription.updated", "subscription.canceled",
91		"invoice.created", "invoice.paid", "invoice.payment_failed", "invoice.voided",
92	}
93	
94	// Errors.
95	var (
96		ErrInvalidURL    = errors.New("invalid webhook URL")
97		ErrInvalidEvents = errors.New("invalid event types")
98	)
99	
100	// CheckURL checks a webhook URL before it is saved: an absolute http or https URL whose host resolves.
101	func (s *Service) CheckURL(ctx context.Context, raw string) error {
102		u, err := url.Parse(raw)
103		if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
104			return fmt.Errorf("%w: use an absolute http or https URL", ErrInvalidURL)
105		}
106		host := u.Hostname()
107		if net.ParseIP(host) != nil {
108			return nil
109		}
110		addrs, err := s.resolver.LookupIPAddr(ctx, host)
111		if err != nil || len(addrs) == 0 {
112			return fmt.Errorf("%w: the host %q does not resolve", ErrInvalidURL, host)
113		}
114		return nil
115	}
116	
117	// CheckEvents checks an endpoint's event types.
118	func CheckEvents(types []string) error {
119		if len(types) == 0 {
120			return fmt.Errorf("%w: name at least one event type, or \"*\"", ErrInvalidEvents)
121		}
122		for _, t := range types {
123			if t != "*" && !slices.Contains(EventTypes, t) {
124				return fmt.Errorf("%w: unknown event type %q", ErrInvalidEvents, t)
125			}
126		}
127		return nil
128	}
129	
130	// NewSecret returns a new signing secret for an endpoint.
131	func NewSecret() string { return store.NewToken("whsec_") }
132	
133	// Sign returns the signature of a delivery's body: the hex HMAC-SHA256 of the body, keyed with the endpoint's secret.
134	func Sign(secret string, body []byte) string {
135		m := hmac.New(sha256.New, []byte(secret))
136		m.Write(body)
137		return hex.EncodeToString(m.Sum(nil))
138	}
139	
140	// Publish records an event and queues a delivery of it to every enabled endpoint of the organization that subscribes to its
141	// type. The deliveries are sent by RunDue.
142	func (s *Service) Publish(ctx context.Context, orgID, eventType string, data any) error {
143		raw, err := json.Marshal(data)
144		if err != nil {
145			return err
146		}
147		now := s.clock.Now()
148		e, err := s.store.AddEvent(orgID, eventType, raw, now)
149		if err != nil {
150			return err
151		}
152		for _, ep := range s.store.WebhookEndpoints(orgID) {
153			if !ep.Enabled || !(slices.Contains(ep.Events, "*") || slices.Contains(ep.Events, eventType)) {
154				continue
155			}
156			next := now
157			if _, err := s.store.CreateDelivery(store.Delivery{OrgID: orgID, EndpointID: ep.ID, EventID: e.ID, NextAttemptAt: &next}, now); err != nil {
158				return err
159			}
160		}
161		return nil
162	}
163	
164	// RunDue attempts every delivery that is due and returns how many it attempted. An answer with a 2xx status marks a delivery
165	// succeeded. Any other failure schedules a retry (see retryWaits) until the delivery has had maxAttempts attempts; a 410 Gone
166	// answer fails it at once and disables its endpoint.
167	func (s *Service) RunDue(ctx context.Context) (int, error) {
168		n := 0
169		for _, d := range s.store.DueDeliveries(s.clock.Now()) {
170			if err := ctx.Err(); err != nil {
171				return n, err
172			}
173			// An earlier attempt in this run may have disabled the endpoint, which unschedules its other deliveries.
174			if cur, ok := s.store.Delivery(d.ID); !ok || cur.Status != store.DeliveryPending || cur.NextAttemptAt == nil {
175				continue
176			}
177			s.deliver(ctx, d)
178			n++
179		}
180		return n, nil
181	}
182	
183	// Body is what a delivery POSTs.
184	type Body struct {
185		ID        string          `json:"id"`
186		Type      string          `json:"type"`
187		CreatedAt time.Time       `json:"created_at"`
188		Data      json.RawMessage `json:"data"`
189	}
190	
191	func (s *Service) deliver(ctx context.Context, d store.Delivery) {
192		status, errText, retryable := 0, "", false
193		ep, ok := s.store.WebhookEndpoint(d.OrgID, d.EndpointID)
194		e, eok := s.store.EventByID(d.EventID)
195		switch {
196		case !ok || !ep.Enabled:
197			errText = "the endpoint is disabled or was deleted"
198		case !eok:
199			errText = "the event no longer exists"
200		default:
201			status, errText = s.send(ctx, ep, e)
202			retryable = errText != "" && status != http.StatusGone
203		}
204		now := s.clock.Now()
205		updated, err := s.store.UpdateDelivery(d.ID, func(d *store.Delivery) error {
206			d.Attempts++
207			d.LastAttemptAt = &now
208			d.NextAttemptAt = nil
209			d.ResponseStatus = status
210			d.Error = errText
211			switch {
212			case errText == "":
213				d.Status = store.DeliverySucceeded
214			case retryable && d.Attempts < maxAttempts:
215				next := now.Add(retryWaits[d.Attempts-1])
216				d.Status = store.DeliveryPending
217				d.NextAttemptAt = &next
218			default:
219				d.Status = store.DeliveryFailed
220			}
221			return nil
222		})
223		if err != nil {
224			return
225		}
226		if status == http.StatusGone {
227			s.disable(d.OrgID, d.EndpointID)
228		}
229		if updated.Status == store.DeliveryFailed && retryable {
230			s.notifyFailure(ctx, ep, updated, now)
231		}
232	}
233	
234	// disable turns off an endpoint that answered 410 Gone, and unschedules its other pending deliveries so none is sent.
235	func (s *Service) disable(orgID, endpointID string) {
236		_, _ = s.store.UpdateWebhookEndpoint(orgID, endpointID, func(ep *store.WebhookEndpoint) error {
237			ep.Enabled = false
238			ep.DisabledReason = "gone"
239			return nil
240		})
241		for _, p := range s.store.Deliveries(orgID, endpointID) {
242			if p.Status == store.DeliveryPending {
243				_, _ = s.store.UpdateDelivery(p.ID, func(x *store.Delivery) error {
244					x.NextAttemptAt = nil
245					return nil
246				})
247			}
248		}
249	}
250	
251	// notifyFailure emails every owner of the endpoint's organization that a delivery has failed for good. It sends at most one
252	// such email per endpoint in failureMailInterval.
253	func (s *Service) notifyFailure(ctx context.Context, ep store.WebhookEndpoint, d store.Delivery, now time.Time) {
254		s.mu.Lock()
255		if last, ok := s.mailed[ep.ID]; ok && now.Sub(last) < failureMailInterval {
256			s.mu.Unlock()
257			return
258		}
259		s.mailed[ep.ID] = now
260		s.mu.Unlock()
261		body := fmt.Sprintf("Tally could not deliver an event to %s after %d attempts, so that delivery has failed for good.\n\nThe last attempt failed: %s.\n", ep.URL, d.Attempts, d.Error)
262		for _, m := range s.store.Members(ep.OrgID) {
263			if m.Role != store.RoleOwner {
264				continue
265			}
266			u, ok := s.store.User(m.UserID)
267			if !ok {
268				continue
269			}
270			_ = s.mail.Send(ctx, mail.Message{To: u.Email, Subject: "Webhook endpoint failing: " + ep.URL, Body: body})
271		}
272	}
273	
274	// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
275	func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
276		body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
277		if err != nil {
278			return 0, err.Error()
279		}
280		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
281		defer cancel()
282		req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
283		if err != nil {
284			return 0, err.Error()
285		}
286		req.Header.Set("Content-Type", "application/json")
287		req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
288		req.Header.Set("Tally-Event-Id", e.ID)
289		req.Header.Set("Tally-Event-Type", e.Type)
290		req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
291		resp, err := s.doer.Do(req)
292		if err != nil {
293			return 0, err.Error()
294		}
295		defer resp.Body.Close()
296		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
297		if resp.StatusCode < 200 || resp.StatusCode > 299 {
298			return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)
299		}
300		return resp.StatusCode, ""
301	}
302

