234	// disable turns off an endpoint that answered 410 Gone, and unschedules its other pending deliveries so none is sent.
235	func (s *Service) disable(orgID, endpointID string) {
236		_, _ = s.store.UpdateWebhookEndpoint(orgID, endpointID, func(ep *store.WebhookEndpoint) error {
237			ep.Enabled = false
238			ep.DisabledReason = "gone"
239			return nil
240		})
241		for _, p := range s.store.Deliveries(orgID, endpointID) {
242			if p.Status == store.DeliveryPending {
243				_, _ = s.store.UpdateDelivery(p.ID, func(x *store.Delivery) error {
244					x.NextAttemptAt = nil
245					return nil
246				})
247			}
248		}
249	}
