251	// notifyFailure emails every owner of the endpoint's organization that a delivery has failed for good. It sends at most one
252	// such email per endpoint in failureMailInterval.
253	func (s *Service) notifyFailure(ctx context.Context, ep store.WebhookEndpoint, d store.Delivery, now time.Time) {
254		s.mu.Lock()
255		if last, ok := s.mailed[ep.ID]; ok && now.Sub(last) < failureMailInterval {
256			s.mu.Unlock()
257			return
258		}
259		s.mailed[ep.ID] = now
260		s.mu.Unlock()
261		body := fmt.Sprintf("Tally could not deliver an event to %s after %d attempts, so that delivery has failed for good.\n\nThe last attempt failed: %s.\n", ep.URL, d.Attempts, d.Error)
262		for _, m := range s.store.Members(ep.OrgID) {
263			if m.Role != store.RoleOwner {
264				continue
265			}
266			u, ok := s.store.User(m.UserID)
267			if !ok {
268				continue
269			}
270			_ = s.mail.Send(ctx, mail.Message{To: u.Email, Subject: "Webhook endpoint failing: " + ep.URL, Body: body})
271		}
272	}
