274	// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
275	func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
276		body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
277		if err != nil {
278			return 0, err.Error()
279		}
280		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
281		defer cancel()
282		req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
283		if err != nil {
284			return 0, err.Error()
285		}
286		req.Header.Set("Content-Type", "application/json")
287		req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
288		req.Header.Set("Tally-Event-Id", e.ID)
289		req.Header.Set("Tally-Event-Type", e.Type)
290		req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
291		resp, err := s.doer.Do(req)
292		if err != nil {
293			return 0, err.Error()
294		}
295		defer resp.Body.Close()
296		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
297		if resp.StatusCode < 200 || resp.StatusCode > 299 {
298			return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)
299		}
300		return resp.StatusCode, ""
301	}
